(() => { const root=document.documentElement, buttons=[...document.querySelectorAll('[data-theme-value]')]; const apply=t=>{t==='auto'?root.removeAttribute('data-theme'):root.setAttribute('data-theme',t);buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.themeValue===t)));}; buttons.forEach(b=>b.addEventListener('click',()=>apply(b.dataset.themeValue))); apply('auto'); })();
